import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{r as t}from"./ThemeToggle-2sZo9z4q.js";import{A as n,C as r,E as i,M as a,N as o,O as s,P as c,_ as l,a as u,b as d,c as f,k as p,l as m,n as h,o as g,t as _,u as v,v as y}from"./shared-JA1PGxXr.js";import{t as b}from"./settings-iYueKX5i.js";import{t as x}from"./shield-check-r4OxDZ2w.js";import{t as S}from"./CodeEditor-DqHMt3P8.js";var C=t(`Cookie`,[[`path`,{d:`M12 2a10 10 0 1 0 10 10 4 4 0 0 1-5-5 4 4 0 0 1-5-5`,key:`laymnq`}],[`path`,{d:`M8.5 8.5v.01`,key:`ue8clq`}],[`path`,{d:`M16 15.5v.01`,key:`14dtrp`}],[`path`,{d:`M12 12v.01`,key:`u5ubse`}],[`path`,{d:`M11 17v.01`,key:`1hyl5a`}],[`path`,{d:`M7 14v.01`,key:`uct60s`}]]),w=e(),T=`Этап 4 · Блок 13 · FastAPI как цельное приложение`;function E({module:e}){return(0,w.jsxs)(o,{children:[(0,w.jsx)(a,{variant:`project`,chip:e??T,title:`Безопасность cookie`,intro:`Укрепим уже знакомую настройку представления: отделим предпочтение клиента от решений сервера о доступе и подключим Secure к централизованной конфигурации.`,tags:[{icon:(0,w.jsx)(C,{size:14}),label:`cookie как ввод клиента`},{icon:(0,w.jsx)(b,{size:14}),label:`настройка Secure`},{icon:(0,w.jsx)(x,{size:14}),label:`границы защиты`}]}),(0,w.jsxs)(c,{number:`00`,title:`От предпочтения к границам доверия`,children:[(0,w.jsx)(s,{children:`В предыдущем целевом шаге браузер запоминал выбор compact или detailed и возвращал его серверу в следующем запросе. Теперь посмотрим, что меняется, если содержимое cookie контролирует сам клиент.`}),(0,w.jsx)(p,{variant:`connected`,items:[{title:`Точка старта`,description:`У нас есть предпочтение вида, которое путешествует между запросами в cookie. Список задач и JSON Planner продолжают жить своим прежним путём.`},{title:`Новый вопрос`,description:`Можем ли мы считать значение надёжным только потому, что раньше его отправил сервер, и как выбрать Secure для HTTP или HTTPS?`},{title:`Результат`,description:`Мы безопасно обрабатываем подмену и задаём политику cookie в Settings, не превращая preference в пользователя, роль или право.`}]}),(0,w.jsx)(`p`,{children:`Дальше разберём отдельно две вещи: значение, которое пришло от клиента, и правила приложения, которые мы задаём сами. Затем пройдём настройку через уже собранный объект и проверим, что установка и сброс cookie остаются согласованными. Это продолжение JSON Planner, а не начало авторизации или нового хранилища.`})]}),(0,w.jsxs)(c,{number:`01`,title:`Cookie приносит выбор клиента, а не доказательство личности`,children:[(0,w.jsx)(s,{children:`Браузер может сохранить cookie после ответа сервера, но следующий запрос всё равно содержит данные, присланные клиентом. Пользователь может удалить или заменить их вручную. Поэтому сервер проверяет значение на каждом входе и ограничивает его назначение.`}),(0,w.jsx)(`p`,{children:`Представим небольшую записку, которую посетитель носит с собой. При первом входе мы написали на ней предпочтительный размер карточек. Посетитель может показать записку, стереть её или переписать. Она помогает выбрать удобное представление, но не подтверждает, кто перед нами. Здесь браузер похож на носителя, cookie на записку, а проверка допустимых значений на правило приёма. Граница аналогии в том, что HTTP-атрибуты дополнительно регулируют отправку записки, а не её правдивость.`}),(0,w.jsx)(`p`,{children:"У `planner_view` допустимы только compact и detailed. Если приходит неизвестное значение вроде admin, обработчик чтения может безопасно выбрать compact. Это предпочтение не должно менять список задач, путь к JSON, статистику, команды CLI или доступ к операциям. Если когда-нибудь появятся аккаунты и права, их нельзя выводить из этой cookie: для этого понадобятся отдельные проверенные данные пользователя и отдельная политика доступа."}),(0,w.jsxs)(_,{caption:`Cookie проходит через границу клиента, но не становится источником прав.`,orientation:`horizontal`,children:[(0,w.jsxs)(g,{label:`Путь preference-cookie`,orientation:`horizontal`,children:[(0,w.jsx)(f,{title:`Клиент`,children:(0,w.jsx)(m,{title:`Браузер`,shape:`process`,children:(0,w.jsx)(`p`,{children:`Отправляет planner_view и может изменить его значение.`})})}),(0,w.jsx)(u,{forward:`Cookie в запросе`,reverse:`Set-Cookie в ответе`}),(0,w.jsxs)(f,{title:`Приложение`,children:[(0,w.jsx)(m,{title:`FastAPI`,shape:`decision`,children:(0,w.jsx)(`p`,{children:`Оставляет допустимый view или использует compact как fallback.`})}),(0,w.jsx)(h,{label:`только формат ответа`}),(0,w.jsx)(m,{title:`Ответ`,shape:`terminator`,children:(0,w.jsx)(`p`,{children:`Настройка не выбирает пользователя и не меняет Task.`})})]})]}),(0,w.jsx)(v,{title:`Что остаётся за пределами cookie`,children:`JSON-хранилище, права на задачи и состояние Planner не должны зависеть от присланного preference.`})]}),(0,w.jsx)(d,{question:`Мы получили planner_view=admin. Что безопасно сделать при чтении предпочтения?`,options:[`Вернуть compact как значение по умолчанию и не менять доступ.`,`Считать admin ролью и открыть дополнительные задачи.`,`Использовать admin как новое имя файла JSON.`],correctIndex:0,explanation:`Cookie управляет только видом. Неизвестное значение не должно расширять права, менять предметные данные или выбирать другой storage.`}),(0,w.jsx)(i,{tone:`info`,children:`Скрытое поле или случайное имя cookie тоже не доказывает, что значение пришло от сервера. Здесь мы делаем значение безопасным по назначению, а не секретным.`})]}),(0,w.jsxs)(c,{number:`02`,title:`У команды и у сохранённой cookie разные правила ошибок`,children:[(0,w.jsx)(s,{children:`В целевом состоянии после предыдущего шага есть два пути к значению view: клиент отправляет новое значение в PUT body или браузер повторно присылает сохранённую cookie в GET. Эти входы решают разные задачи, поэтому и реакция на ошибку у них разная.`}),(0,w.jsx)(`p`,{children:`PUT body является командой: клиент просит сохранить один из заранее разрешённых вариантов. Ограниченная схема с Literal принимает только compact или detailed. Если body содержит другое значение, FastAPI возвращает 422, а прежняя cookie остаётся неизменной. Так клиент получает ясный отказ и может исправить запрос.`}),(0,w.jsx)(`p`,{children:`Cookie в GET является необязательным напоминанием о предпочтении. Она могла устареть, быть вручную изменена или принадлежать старой версии приложения. Для такого несрочного значения можно выбрать безопасный fallback compact. Ответ остаётся доступным, а неизвестная строка не превращается в команду. Это не разрешение принимать произвольный body: новая команда всё ещё проходит строгую схему.`}),(0,w.jsx)(`p`,{children:`Сравним с закладкой в книге: если закладка потерялась, мы можем открыть книгу с начала. Но если в форме заказа написан неизвестный товар, мы не должны молча заменить его случайным. В первом случае теряется только удобство, во втором неверно выполнится явная команда. Аналогия ограничена тем, что HTTP-ответы имеют конкретный контракт: здесь для неправильного body уже определён 422, а для неизвестной cookie определён fallback.`}),(0,w.jsx)(r,{code:`raw = "false"
cookie_secure = bool(raw)
print(cookie_secure)`,question:`Почему этот короткий разбор конфигурации ошибочен?`,options:[`Любая непустая строка в Python считается истинной, включая текст false.`,`bool принимает только целые числа.`,`Строку нельзя прочитать из окружения.`],correctIndex:0,explanation:`Переменная окружения приходит строкой. bool(raw) проверяет, пуста ли строка, а не означает ли она слово false. Для настройки нужны явные разрешённые записи и ошибка для неизвестной строки.`}),(0,w.jsx)(`p`,{children:`Есть ещё важное различие. Неизвестная cookie не должна ломать чтение несущественной настройки, поэтому для неё подходит заранее выбранный fallback. Неизвестная настройка сервера, напротив, задаёт политику безопасности всего приложения. Её нельзя тихо превращать в False, потому что ошибка маскируется под работающий режим.`})]}),(0,w.jsxs)(c,{number:`03`,title:`Каждый атрибут решает отдельную задачу`,children:[(0,w.jsx)(s,{children:`Флаги cookie не складываются в универсальную защиту. Мы проверим каждый по вопросу, на который он отвечает, и не припишем ему функцию проверки пользователя.`}),(0,w.jsx)(`p`,{children:`HttpOnly запрещает доступ к cookie из JavaScript в браузере, но браузер всё равно может автоматически отправлять её вместе с подходящим запросом. Secure ограничивает отправку cookie защищённым HTTPS-соединением. Он не создаёт HTTPS, не шифрует приложение сам по себе и не подтверждает, что сервер действительно развёрнут правильно.`}),(0,w.jsx)(`p`,{children:`SameSite=lax ограничивает часть отправок в межсайтовом контексте. Это отдельное правило браузера, которое зависит от вида перехода и окружения. Само значение в заголовке Set-Cookie не доказывает, что любой HTTP-клиент исполнил браузерную политику. Для учебной preference cookie мы сохраняем HttpOnly=True, SameSite=lax и не объявляем их авторизацией.`}),(0,w.jsx)(n,{rows:[[`HttpOnly`,`JavaScript не читает cookie; автоматическая отправка браузером остаётся возможной.`],[`Secure`,`Браузер отправляет cookie по HTTPS; флаг не поднимает TLS-сервер.`],[`SameSite=lax`,`Ограничивается часть межсайтовых отправок; это не проверка прав.`],[`Path=/preferences`,`Cookie отправляется для соответствующей области пути.`],[`Domain отсутствует`,`Не расширяем область cookie на другие поддомены.`],[`Expires и Max-Age отсутствуют`,`Это cookie браузерной сессии, не серверная login-сессия.`]]}),(0,w.jsx)(`p`,{children:`Слово «сессия» здесь легко спутать. Session-cookie говорит о сроке хранения на стороне браузера. Server-side session означала бы состояние, которое сервер связывает с клиентом, например вход в аккаунт. У нас такого механизма нет. Закрытие и повторное открытие браузера тоже не доказывает logout: браузер может восстановить сессию и её cookie.`}),(0,w.jsx)(i,{children:`Для preference-cookie не нужно хранить секреты. Cookie хранит компактный выбор вида, а все полномочия остаются за пределами этого ресурса.`})]}),(0,w.jsxs)(c,{number:`04`,title:`Secure выбираем при сборке настроек`,children:[(0,w.jsx)(s,{children:`В локальной разработке HTTP помогает запускать API без настроенного TLS, поэтому Secure по умолчанию остаётся выключенным. В HTTPS-окружении приложение должно получить явное true из конфигурации.`}),(0,w.jsx)(`p`,{children:`Значение из окружения всегда начинается как строка. Слова true и false не являются специальными значениями Python, пока мы сами не разберём их по точному правилу. Нормализация регистра может позволить TRUE и False, но список допустимых слов остаётся коротким. Пустое или неизвестное значение не должно незаметно выключать защитную политику.`}),(0,w.jsx)(l,{code:`print(bool("false"))
print(bool(""))`,output:`True
False`,hint:`Представим, что bool проверяет пустоту строки, а не читает английское слово как логическое значение.`}),(0,w.jsx)(`p`,{children:`Мы отдельно задаём поведение для отсутствующей настройки и для некорректной. Отсутствующее значение может получить документированный локальный default False. Если задано непонятное слово, приложение должно сообщить о недопустимом COOKIE_SECURE при создании Settings. Ошибка возникает один раз на границе сборки, до обработки запросов, а не всплывает по-разному внутри каждого endpoint.`}),(0,w.jsx)(`p`,{children:`Представим общую панель освещения в здании: администратор задаёт режим один раз, а помещения получают уже собранное правило. Если каждый работник отдельно угадывает режим по записке, ответы разойдутся. Здесь Settings похож на панель, а dependency на курьера, который передаёт готовую настройку обработчику. Но аналогия не делает dependency проверкой доступа: она только доставляет значение, а решение о полномочиях в этом маршруте вообще не принимается.`}),(0,w.jsx)(`p`,{children:`Secure не обязан быть привязан к каждому request отдельной переменной окружения. Мы расширяем существующий Settings полем cookie_secure, читаем и проверяем его в уже имеющейся точке сборки, а затем применяем к установке cookie. Так один и тот же проект получает понятное локальное поведение и явную настройку для HTTPS.`})]}),(0,w.jsxs)(c,{number:`05`,title:`Создаём dependency для уже созданного Settings`,children:[(0,w.jsx)(s,{children:`После урока 65.1 app.state.settings уже содержит готовый Settings, но provider для него ещё отсутствует. В этом занятии мы добавим get_settings и SettingsDep, применив знакомые Depends и Annotated.`}),(0,w.jsx)(`p`,{children:`В app/api.py приложение уже сохраняет собранный Settings в app.state.settings. Мы создадим get_settings в app/core/dependencies.py: он принимает Request и возвращает request.app.state.settings. Затем объявим SettingsDep = Annotated[Settings, Depends(get_settings)] и используем этот тип в preference-router. Provider не создаёт новый Settings и не читает окружение.`}),(0,w.jsx)(`p`,{children:`Путь значения остаётся один: окружение читается во время настройки приложения, проверенный объект сохраняется в app.state.settings, а новый provider только возвращает его обработчику. Preference-операция берёт cookie_secure и применяет его к ответу. Мы не добавляем прямой os.environ в handler, не создаём Settings на каждый request и не меняем зависимость Planner.`}),(0,w.jsx)(`p`,{children:`Ниже показан фрагмент цепочки настройки, а не самостоятельная программа: типы и создание приложения остаются в уже существующих модулях проекта.`}),(0,w.jsx)(y,{code:`from typing import Annotated
from fastapi import Depends, Request
from app.core.config import Settings

# app/api.py уже сохраняет этот объект
app.state.settings = settings

# Добавляем в app/core/dependencies.py
def get_settings(request: Request) -> Settings:
    return request.app.state.settings

SettingsDep = Annotated[Settings, Depends(get_settings)]

# В preference-router.py
settings: SettingsDep
secure = settings.cookie_secure`,steps:[{line:5,note:`В app/api.py уже хранится собранный объект.`,vars:{"app.state.settings":`готовый Settings`}},{line:8,note:`В этом занятии добавляем provider, который получает Request.`,vars:{get_settings:`новая dependency`}},{line:9,note:`Provider читает единственный источник Settings.`,vars:{"request.app.state.settings":`тот же объект`}},{line:11,note:`Создаём типизированный alias на Depends(get_settings).`,vars:{SettingsDep:`Settings через Depends`}},{line:14,note:`Обработчик получает сохранённый Settings через alias.`,vars:{settings:`готовый объект`}},{line:15,note:`Preference-операция читает только нужное поле.`,vars:{cookie_secure:`политика ответа`}}]}),(0,w.jsx)(`p`,{children:`Тестовая подмена провайдера полезна, когда мы проверяем другой набор настроек. После проверки override нужно очистить, чтобы он не повлиял на следующий сценарий. Это знакомый инструмент DI, а не новый Settings и не требование менять CLI: CLI по-прежнему получает настройки на своём пути сборки.`})]}),(0,w.jsxs)(c,{number:`06`,title:`Установка и удаление должны обращаться к той же cookie`,children:[(0,w.jsx)(s,{children:`Сервер не хранит preference-cookie в собственном словаре. Он просит браузер сохранить её через Set-Cookie, а для сброса отправляет заголовок Set-Cookie с истёкшим сроком.`}),(0,w.jsx)(`p`,{children:`Чтобы увидеть независимую механику, рассмотрим cookie dismissed_tour на пути /help. Ответ с set_cookie сообщает браузеру имя, значение, путь и атрибуты. Если позже мы хотим её удалить, response.delete_cookie создаёт новый заголовок, который просит забыть эту запись. Сброс не удаляет серверную сессию и не отменяет аккаунт: такого состояния в примере нет.`}),(0,w.jsx)(S,{caption:`Фрагмент независимого примера: cookie показа подсказки в справке`,code:`response.set_cookie(
    key="dismissed_tour",
    value="yes",
    path="/help",
    secure=True,
    httponly=True,
    samesite="lax",
)

response.delete_cookie(
    key="dismissed_tour",
    path="/help",
    secure=True,
    httponly=True,
    samesite="lax",
)`}),(0,w.jsx)(`p`,{children:`Браузер различает cookie по имени, домену и пути. Поэтому удаление с другим Path может оставить старую запись: ключ как будто указывает на другую область. В проектном ресурсе сохраняем Path=/preferences и отсутствие Domain при установке и удалении. Атрибуты Secure, HttpOnly и SameSite описывают политику отправки, а не являются идентификаторами записи, но мы передаём их согласованно для ясного контракта.`}),(0,w.jsx)(`p`,{children:`Если PUT устанавливает новую настройку, ответ должен применять cookie_secure из Settings и сохранить прежние HttpOnly=True, SameSite=lax, Path и session-cookie. DELETE обращается к той же записи и сохраняет прежний статус 204 без тела. Диагностический response header должен остаться на том объекте Response, который действительно отправляется. Мы укрепляем политику существующего ресурса и не переписываем его CRUD.`}),(0,w.jsx)(`p`,{children:`Браузер хранит запись, а сервер видит её снова только тогда, когда клиент отправляет подходящий запрос. Это как номерок гардероба, который посетитель приносит обратно: сотрудник может принять номерок как указание, какую куртку искать, но сам номерок не доказывает право собственности. Граница аналогии в том, что реальный серверный ресурс обычно требует собственную проверку прав; preference-cookie такую проверку не заменяет.`})]}),(0,w.jsxs)(c,{number:`07`,title:`HTTP-проверка показывает заголовки, но не всю безопасность браузера`,children:[(0,w.jsx)(s,{children:`Мы можем проверить контракт по реальным запросам клиента, не называя это полным аудитом TLS или браузерной политики.`}),(0,w.jsx)(`p`,{children:`Для проверки атрибутов полезны отдельные клиенты с независимыми cookie jar. Мы сравниваем локальный default HTTP и экземпляр, которому Settings передал Secure=True, проверяем Set-Cookie, повторный GET и DELETE. После неверного PUT прежний корректный view остаётся; после подмены входной cookie GET возвращает compact. Отдельный сценарий убеждается, что список задач, stats и CLI не зависят от preference.`}),(0,w.jsx)(`p`,{children:`TestClient позволяет пройти FastAPI-приложение и увидеть HTTP-контракт. HTTPS base_url может проверить поведение cookie jar клиента при адресе HTTPS, но он не запускает настоящий TLS-сервер и не проверяет сертификат, reverse proxy или настройки production. Тест может увидеть атрибут SameSite в заголовке, но это не означает, что библиотека воспроизвела все решения браузера о межсайтовой отправке. HttpOnly также оцениваем как атрибут, а не как полномасштабную защиту от скриптов.`}),(0,w.jsx)(`p`,{children:`Неверный COOKIE_SECURE проверяем отдельно на точке сборки и убеждаемся, что ошибка называет настройку. Не подменяем её на False ради прохождения теста. Тестовые Settings и JSON должны быть изолированы от рабочей среды, а overrides восстанавливаются после проверки. Так мы получаем достоверное доказательство поведения программы без обещаний, которые сам инструмент дать не может.`}),(0,w.jsx)(d,{question:`Что доказывает тест, в котором TestClient использует HTTPS base_url?`,options:[`Мы наблюдаем поведение клиента и заголовки внутри тестового ASGI-приложения.`,`В проекте уже настроен реальный HTTPS-сервер и проверен его сертификат.`,`Браузеры гарантированно применят тот же SameSite-контекст.`],correctIndex:0,explanation:`Тест проверяет выбранный URL и поведение тестового клиента. TLS-сервер, сертификат и политику браузера нужно проверять в соответствующем окружении.`})]}),(0,w.jsxs)(c,{number:`08`,title:`Что мы будем делать в практике`,children:[(0,w.jsx)(s,{children:`Теперь мы укрепим тот же Planner: preference останется маленькой настройкой вида, а API задач и JSON продолжат работать по прежнему пути.`}),(0,w.jsx)(p,{variant:`connected`,items:[{title:`Зададим политику`,description:`Добавим COOKIE_SECURE в существующий Settings, оставим локальный HTTP default и отклоним неизвестную строку при сборке.`},{title:`Передадим готовую настройку`,description:`Создадим get_settings/SettingsDep в app/core/dependencies.py и подключим preference-операции к уже сохранённому app.state.settings, сохранив общий Planner.`},{title:`Согласуем ответы`,description:`Проверим установку и удаление с одинаковой областью cookie, Secure из Settings, прежним HTTP-контрактом и 204 без тела.`},{title:`Проверим границы доверия`,description:`Сравним независимые cookie jar, допустимое значение, fallback, неверный body и подмену cookie без изменения прав или JSON_PATH.`},{title:`Подтвердим старые возможности`,description:`На изолированных данных выполним короткую регрессию Task API, stats и CLI, не подключая базу данных или авторизацию.`}]}),(0,w.jsx)(`p`,{children:`По маршруту к практике мы подойдём с файловым Planner, централизованной сборкой настроек, dependency-графом и preference-ресурсом предыдущего шага. Мы изменим только конфигурацию и применение её к существующей cookie. Неправильная серверная настройка должна остановить сборку, неизвестная cookie должна безопасно вернуться к compact, а изменение вида не должно менять задачу, статистику или выбор хранилища.`}),(0,w.jsx)(`p`,{children:`После проверки передадим следующему блоку работающий JSON Planner с понятными Settings и dependencies. Там мы исследуем ограничения полного чтения и записи файла. SQLite, SQLAlchemy, Engine, Session и ORM в этом занятии ещё не появляются.`})]})]})}export{E as Lesson65_2};